steps.command:
var reportNumber = ServiceManager.getInput("REPORT_NUMBER");
var ReportPurpose = ServiceManager.getInput("REPORT_PURPOSE");

var ReportReceipts = ServiceManager.getInput("REPORT_CREDIT_RECEIPTS");
if (typeof ReportReceipts === "string") {
    try {
        ReportReceipts = JSON.parse(ReportReceipts);
    } catch (parseError) {
        throw new Error(
            "BLOCKER ReceiptBatch_CreateCreditLinesRPA step=Inputs report=" +
            (reportNumber === null || reportNumber === undefined || String(reportNumber) === "" ? "unknown" : reportNumber) +
            " reason=REPORT_CREDIT_RECEIPTS is not valid JSON."
        );
    }
}
if (!Array.isArray(ReportReceipts)) {
    throw new Error(
        "BLOCKER ReceiptBatch_CreateCreditLinesRPA step=Inputs report=" +
        (reportNumber === null || reportNumber === undefined || String(reportNumber) === "" ? "unknown" : reportNumber) +
        " reason=REPORT_CREDIT_RECEIPTS must be an array or a JSON string containing an array."
    );
}

var creditReceiptIdsCount = ReportReceipts.length;
var CreditTransactions = [];
var CreditCardGroups = [];
var currentCreditCardGroup = null;
var currentCreditTransaction = null;
var creditLinesProcessed = 0;
var creditTotalSelected = 0;
var creditSelectedForCard = 0;
var creditSelectionSucceeded = [];
var creditSelectionErrorMessage = "";
var creditSelectionStatusReceiptId = "";
var creditOnTransactionsPage = true;
var creditCurrentPageTitle = "";

var creditBatchRows =
    ReceiptBatch_getCreditTransactionDetailsBatchResponse.Response
        .ReceiptBatch_getCreditTransactionDetailsBatchElements.CREDIT_TRANSACTIONS;

var creditRowsByReceiptId = {};
for (var creditRowIndex = 0; creditRowIndex < creditBatchRows.length; creditRowIndex++) {
    var creditRow = creditBatchRows[creditRowIndex];
    creditRowsByReceiptId[String(creditRow.RECEIPT_ID)] = creditRow;
}

for (var creditReceiptIndex = 0; creditReceiptIndex < ReportReceipts.length; creditReceiptIndex++) {
    CreditTransactions[creditReceiptIndex] =
        creditRowsByReceiptId[String(ReportReceipts[creditReceiptIndex].RECEIPT_ID)];
}

var creditGroupByCardId = {};
CreditCardGroups = [];

for (var creditGroupReceiptIndex = 0; creditGroupReceiptIndex < creditReceiptIdsCount; creditGroupReceiptIndex++) {
    var creditGroupTransaction = CreditTransactions[creditGroupReceiptIndex];
    var groupCardId = creditGroupTransaction.CARD_ID;
    var groupCardLabel = creditGroupTransaction.CARD_LABEL;

    if (!Object.prototype.hasOwnProperty.call(creditGroupByCardId, groupCardId)) {
        var newCardGroup = {
            CARD_ID: groupCardId,
            CARD_LABEL: groupCardLabel,
            receiptIndexes: []
        };
        creditGroupByCardId[groupCardId] = newCardGroup;
        CreditCardGroups.push(newCardGroup);
    }

    creditGroupByCardId[groupCardId].receiptIndexes.push(creditGroupReceiptIndex);
}

creditSelectionSucceeded[currentCreditReceiptIndex] = false;
creditSelectionErrorMessage =
    ReceiptBatch_selectCreditTransactionError === null ||
    ReceiptBatch_selectCreditTransactionError === undefined
        ? ""
        : String(ReceiptBatch_selectCreditTransactionError);
if (String(creditSelectionErrorMessage).trim() === "") {
    creditSelectionErrorMessage =
        "Credit transaction selection failed without an error message.";
}
var creditSelectionReceipt = ReportReceipts[currentCreditReceiptIndex];
var creditSelectionReceiptId = creditSelectionReceipt && creditSelectionReceipt.RECEIPT_ID;
var creditSelectionReceiptIdText =
    creditSelectionReceiptId === null || creditSelectionReceiptId === undefined
        ? ""
        : String(creditSelectionReceiptId).trim();
if (!/^[0-9]+$/.test(creditSelectionReceiptIdText)) {
    throw new Error("credit Selection Failure: RECEIPT_ID must be numeric, got '" +
        String(creditSelectionReceiptId) + "'.");
}
creditSelectionStatusReceiptId = creditSelectionReceiptIdText;

var creditGotoResponse = iExpense_credit_gotoUpdateTransactionsResponse;
var creditGotoElements =
    (creditGotoResponse &&
     creditGotoResponse.Response &&
     creditGotoResponse.Response.iExpense_credit_gotoUpdateTransactionsElements) || {};

var creditWizardTitle = String(creditGotoElements.WizardTitle === null || creditGotoElements.WizardTitle === undefined ? "" : creditGotoElements.WizardTitle);

var creditBackResponse = ReceiptBatch_creditBackToTransactionsResponse;
var creditBackElements =
    (creditBackResponse &&
     creditBackResponse.Response &&
     creditBackResponse.Response.ReceiptBatch_creditBackToTransactionsElements) || {};

var creditBackTitle = String(creditBackElements.CURRENT_PAGE_TITLE === null || creditBackElements.CURRENT_PAGE_TITLE === undefined ? "" : creditBackElements.CURRENT_PAGE_TITLE);

var creditGotoResponse = iExpense_credit_gotoUpdateTransactionsResponse;
var creditGotoElements =
    (creditGotoResponse &&
     creditGotoResponse.Response &&
     creditGotoResponse.Response.iExpense_credit_gotoUpdateTransactionsElements) || {};

var creditWizardTitle = String(creditGotoElements.WizardTitle === null || creditGotoElements.WizardTitle === undefined ? "" : creditGotoElements.WizardTitle);

var creditFindResponse = ReceiptBatch_findCreditExpenseLineResponse;
var creditFindElements =
    (creditFindResponse &&
     creditFindResponse.Response &&
     creditFindResponse.Response.ReceiptBatch_findCreditExpenseLineElements) || {};

var creditFindMatchCount = Number(creditFindElements.MATCH_COUNT);
if (!isFinite(creditFindMatchCount) || creditFindMatchCount !== 1) {
    throw new Error("credit Line Index: expected exactly one credit expense line, got '" + String(creditFindElements.MATCH_COUNT) + "'.");
}

var creditLineIndexText = creditFindElements.CREDIT_LINE_INDEX === null || creditFindElements.CREDIT_LINE_INDEX === undefined
    ? ""
    : String(creditFindElements.CREDIT_LINE_INDEX).trim();
if (!/^[0-9]+$/.test(creditLineIndexText)) {
    throw new Error("credit Line Index: CREDIT_LINE_INDEX must be numeric, got '" + creditLineIndexText + "'.");
}
var creditLineIndex = Number(creditLineIndexText);

var creditSaveResponse = ReceiptBatch_SaveCreditLineAndReturnResponse;
var creditSaveElements =
    (creditSaveResponse &&
     creditSaveResponse.Response &&
     creditSaveResponse.Response.ReceiptBatch_SaveCreditLineAndReturnElements) || {};

function creditSaveFlagIsTrue(value) {
    return value === true || String(value).toLowerCase() === "true";
}

if (creditSaveFlagIsTrue(creditSaveElements.CashLineErrorMessageExists)) {
    throw new Error("credit Save Line: " + String(creditSaveElements.CashLineErrorMessage === null || creditSaveElements.CashLineErrorMessage === undefined ? "" : creditSaveElements.CashLineErrorMessage));
}
if (creditSaveFlagIsTrue(creditSaveElements.errorPopupExists)) {
    throw new Error("credit Save Line: an error popup appeared.");
}
var creditSaveError = creditSaveElements.Error;
if (creditSaveError !== null && creditSaveError !== undefined && String(creditSaveError).trim() !== "") {
    throw new Error("credit Save Line: " + String(creditSaveError));
}
var creditSaveTitle = String(creditSaveElements.currentPageTitle === null || creditSaveElements.currentPageTitle === undefined ? "" : creditSaveElements.currentPageTitle);
if (creditSaveTitle.indexOf("Expense Report: Credit Card Expenses") === -1) {
    throw new Error("credit Save Line: the save did not return to Expense Report: Credit Card Expenses, got '" + creditSaveTitle + "'.");
}
creditCurrentPageTitle = creditSaveTitle;

errorHandler.command:
(function () {
    function singleLine(value) {
        return String(value === null || value === undefined ? "" : value)
            .replace(/[\r\n]+/g, " ")
            .replace(/^\s+|\s+$/g, "");
    }

    function textOrUnknown(value) {
        var text = singleLine(value);
        return text === "" ? "unknown" : text;
    }

    function bounded(value, maxLength) {
        var text = singleLine(value);
        return text.length > maxLength ? text.substring(0, maxLength) : text;
    }

    var err = ServiceManager.err || {};
    var report = null;
    try {
        report = ServiceManager.getInput("REPORT_NUMBER");
    } catch (ignored) {
        report = null;
    }

    if (report === null || report === undefined || String(report) === "") {
        if (typeof reportNumber !== "undefined" && reportNumber !== null && String(reportNumber) !== "") {
            report = reportNumber;
        } else {
            report = "unknown";
        }
    }

    var stepNumber = err.AP_STEP_NUMBER;
    var stepName = err.AP_STEP_NAME;
    var stepType = err.AP_STEP_TYPE;
    var loopCounter = err.AP_LOOP_COUNTER;
    var originalError = err.AP_ERR_TEXT;

    var message = "BLOCKER process=ReceiptBatch_CreateCreditLinesRPA" +
        " report=" + textOrUnknown(report) +
        " stepNumber=" + textOrUnknown(stepNumber) +
        " stepName=" + textOrUnknown(stepName) +
        " stepType=" + textOrUnknown(stepType);

    if (loopCounter !== null && loopCounter !== undefined && singleLine(loopCounter) !== "") {
        message += " loop=" + singleLine(loopCounter);
    }

    message += " error=" + bounded(originalError === null || originalError === undefined ? "unknown" : originalError, 1000);

    console.log(message);
})();
